@implements IAsyncDisposable
@inject IJSRuntime JS

<div @ref="_wrapperElement">
    @ChildContent
</div>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }
    [Parameter] public int TimeoutSeconds { get; set; } = 300;
    [Parameter] public EventCallback OnIdle { get; set; }
    [Parameter] public EventCallback OnActive { get; set; }

    private ElementReference _wrapperElement;
    private IJSObjectReference? _module;
    private DotNetObjectReference<UserActivityTracker>? _dotNetRef;

    private bool _isIdle;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./Components/UserActivityTracker.razor.js");
            await _module.InvokeVoidAsync("initialize", _wrapperElement, _dotNetRef, TimeoutSeconds * 1000);
        }
    }

    [JSInvokable]
    public async Task OnUserIdle()
    {
        if (!_isIdle)
        {
            _isIdle = true;
            await OnIdle.InvokeAsync();
        }
    }

    [JSInvokable]
    public async Task OnUserActive()
    {
        if (_isIdle)
        {
            _isIdle = false;
            await OnActive.InvokeAsync();
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_module is not null)
        {
            try
            {
                await _module.InvokeVoidAsync("dispose");
                await _module.DisposeAsync();
            }
            catch (JSDisconnectedException)
            {
                // Circuit may already be gone during server-side prerendering teardown.
            }
        }
        _dotNetRef?.Dispose();
    }
}

let state = null;

const ACTIVITY_EVENTS = ["mousemove", "keydown", "click", "scroll"];

function resetTimer() {
    clearTimeout(state.timerId);

    if (state.isIdle) {
        state.isIdle = false;
        state.dotNetRef.invokeMethodAsync("OnUserActive");
    }

    state.timerId = setTimeout(() => {
        state.isIdle = true;
        state.dotNetRef.invokeMethodAsync("OnUserIdle");
    }, state.timeoutMs);
}

export function initialize(element, dotNetRef, timeoutMs) {
    state = { element, dotNetRef, timeoutMs, timerId: null, isIdle: false, handler: resetTimer };

    for (const event of ACTIVITY_EVENTS) {
        element.addEventListener(event, state.handler, { passive: true });
    }

    // Start the initial inactivity countdown.
    state.timerId = setTimeout(() => {
        state.isIdle = true;
        state.dotNetRef.invokeMethodAsync("OnUserIdle");
    }, timeoutMs);
}

export function dispose() {
    if (!state) return;

    clearTimeout(state.timerId);

    for (const event of ACTIVITY_EVENTS) {
        state.element.removeEventListener(event, state.handler);
    }

    state = null;
}

